class Solution {
public:
    int minSumOfLengths(vector<int>& arr, int target) {
        unordered_map<long long,int> last;
        last[0] = -1;
        long long prefix = 0;
        int best = INT_MAX, ans = INT_MAX;
        for (int i = 0; i < (int)arr.size(); ++i) {
            prefix += arr[i];
            auto it = last.find(prefix - target);
            if (it != last.end()) {
                int len = i - it->second;
                if (best != INT_MAX) ans = min(ans, best + len);
                best = min(best, len);
            }
            last[prefix] = i;
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

