class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        n = len(arr)
        left = [float('inf')] * n
        s, cur, best = 0, 0, float('inf')
        for i in range(n):
            cur += arr[i]
            while cur > target:
                cur -= arr[s]
                s += 1
            if cur == target:
                best = min(best, i - s + 1)
            left[i] = best
        s, cur, ans = 0, 0, float('inf')
        for i in range(n):
            cur += arr[i]
            while cur > target:
                cur -= arr[s]
                s += 1
            if cur == target and s > 0 and left[s - 1] != float('inf'):
                ans = min(ans, left[s - 1] + i - s + 1)
        return ans if ans != float('inf') else -1

