        int n = arr.size();
        vector<int> left(n, INT_MAX);
        int s = 0, cur = 0, best = INT_MAX;
        for (int i = 0; i < n; ++i) {
            cur += arr[i];
            while (cur > target) cur -= arr[s++];
            if (cur == target) best = min(best, i - s + 1);
            left[i] = best;
