        s = 0; cur = 0;
        int ans = INT_MAX;
        for (int i = 0; i < n; ++i) {
            cur += arr[i];
            while (cur > target) cur -= arr[s++];
            if (cur == target && s > 0 && left[s - 1] != INT_MAX)
                ans = min(ans, left[s - 1] + i - s + 1);
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

